import json
import sys
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    b = solver.IntVar(0, 10, 'bus_trips')
    c = solver.IntVar(0, sys.maxsize, 'car_trips')

    # Define the objective function
    objective = solver.Objective()
    objective.SetMinimization()
    objective.SetCoefficient(b, 2)
    objective.SetCoefficient(c, 1.5)

    # Add constraints
    solver.Add(100 * b + 40 * c >= 1200)
    solver.Add(b <= 10)
    solver.Add(2 * c >= 3 * b)

    # Solve the problem
    status = solver.Solve()

    # Extract the results
    if status == pywraplp.Solver.OPTIMAL:
        total_time = 2 * b.solution_value() + 1.5 * c.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": total_time
        }
    else:
        result = {
            "status": "NOT_SOLVED",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

