from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define parameters
    num_centers = 5
    num_stores = 7
    opening_costs = [151000, 192000, 114000, 171000, 160000]
    supply_capacities = [1576, 1364, 1697, 891, 1755]
    demands = [566, 673, 787, 1000, 715, 413, 641]
    transport_costs = [
        [5, 2, 3, 3, 3, 5, 4],  # Center 1
        [3, 5, 2, 4, 2, 4, 5],  # Center 2
        [1, 4, 2, 5, 4, 1, 1],  # Center 3
        [3, 3, 2, 4, 4, 3, 4],  # Center 4
        [4, 1, 3, 5, 3, 5, 1]   # Center 5
    ]

    # Decision variables
    y = [solver.IntVar(0, 1, f'y_{i}') for i in range(num_centers)]
    x = [[solver.NumVar(0, solver.infinity(), f'x_{i}_{j}') for j in range(num_stores)] for i in range(num_centers)]

    # Objective function
    objective = solver.Objective()
    for i in range(num_centers):
        objective.SetCoefficient(y[i], opening_costs[i])
        for j in range(num_stores):
            objective.SetCoefficient(x[i][j], transport_costs[i][j])
    objective.SetMinimization()

    # Supply capacity constraints
    for i in range(num_centers):
        supply_expr = solver.Sum(x[i][j] for j in range(num_stores))
        solver.Add(supply_expr <= supply_capacities[i] * y[i])

    # Demand constraints
    for j in range(num_stores):
        demand_expr = solver.Sum(x[i][j] for i in range(num_centers))
        solver.Add(demand_expr == demands[j])

    # Solve
    status = solver.Solve()

    # Calculate total cost
    total_cost = 0
    for i in range(num_centers):
        total_cost += opening_costs[i] * y[i].solution_value()
        for j in range(num_stores):
            total_cost += transport_costs[i][j] * x[i][j].solution_value()

    # Prepare result
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_SOLVED",
        "objective_value": total_cost
    }
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

