    capacities = {
        (0, 1): 14,
        (0, 2): 15,
        (0, 3): 13,
        (0, 5): 4,
        (1, 0): 10,
        (1, 2): 7,
        (1, 3): 18,
        (1, 4): 9,
        (1, 5): 5,
        (2, 0): 11,
        (2, 3): 7,
        (2, 4): 13,
        (2, 5): 6,
        (3, 0): 7,
        (3, 1): 11,
        (3, 2): 18,
        (3, 4): 17,
        (3, 5): 2,
        (4, 0): 19,
        (4, 1): 8,
        (4, 2): 15,
        (4, 3): 15,
        (4, 5): 5,
        (5, 0): 10,
        (5, 1): 19,
        (5, 2): 17,
        (5, 3): 2,
        (5, 4): 3
    }

    # Create variables
    x = {}
    for i in cities:
        for j in cities:
