            incoming = solver.Sum([x[(j, i)] for j in cities if j != i])
            outgoing = solver.Sum([x[(i, j)] for j in cities if j != i])
            solver.Add(incoming - outgoing == 0)

    # Solve the problem
    status = solver.Solve()

