from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')
    if not solver:
        print("Solver not found.")
        return

    # Define parameters
    cities = ['New York', 'Los Angeles', 'Chicago', 'Atlanta']
    regions = ['Region 1', 'Region 2', 'Region 3']
    fixed_costs = {
        'New York': 400,
        'Los Angeles': 500,
        'Chicago': 300,
        'Atlanta': 150
    }
    shipping_costs = {
        'New York': {'Region 1': 20, 'Region 2': 40, 'Region 3': 50},
        'Los Angeles': {'Region 1': 48, 'Region 2': 15, 'Region 3': 26},
        'Chicago': {'Region 1': 26, 'Region 2': 35, 'Region 3': 18},
        'Atlanta': {'Region 1': 24, 'Region 2': 50, 'Region 3': 35}
    }
    demands = {
        'Region 1': 80,
        'Region 2': 70,
        'Region 3': 40
    }

    # Create binary variables for warehouse openings
    x = {}
    for city in cities:
        x[city] = solver.IntVar(0, 1, f'x_{city}')

    # Create integer variables for units shipped from each warehouse to each region
    y = {}
    for city in cities:
        y[city] = {}
        for region in regions:
            y[city][region] = solver.IntVar(0, 100, f'y_{city}_{region}')

    # Objective function: minimize total cost
    objective = solver.Objective()
    for city in cities:
        objective.SetCoefficient(x[city], fixed_costs[city])
    for city in cities:
        for region in regions:
            objective.SetCoefficient(y[city][region], shipping_costs[city][region])
    objective.SetMinimization()

    # Warehouse capacity constraints
    for city in cities:
        total_shipped = solver.Sum([y[city][region] for region in regions])
        solver.Add(total_shipped <= 100 * x[city])

    # Demand satisfaction constraints
    for region in regions:
        total_received = solver.Sum([y[city][region] for city in cities])
        solver.Add(total_received == demands[region])

    # Constraint 1: If New York is opened, Los Angeles must be opened
    solver.Add(x['New York'] <= x['Los Angeles'])

    # Constraint 2: At most two warehouses can be opened
    solver.Add(solver.Sum([x[city] for city in cities]) <= 2)

    # Constraint 3: Either Atlanta or Los Angeles must be opened
    solver.Add(x['Atlanta'] + x['Los Angeles'] >= 1)

    # Solve the problem
    status = solver.Solve()

    # Extract the objective value
    objective_value = objective.Value()

    # Print the result
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

