        'Wednesday': ['Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'],
        'Thursday': ['Thursday', 'Friday', 'Saturday', 'Sunday', 'Monday'],
        'Friday': ['Friday', 'Saturday', 'Sunday', 'Monday', 'Tuesday'],
