    solver.Add(x + y + z <= 5000)

    # Minimum allocation difference: x >= y + 50
    solver.Add(x >= y + 50)

    # Difference between Z and (X + Y): 1000 <= z - (x + y) <= 200
    solver.Add(z - (x + y) >= 1000)
    solver.Add(z - (x + y) <= 200)

    # Maximum individual allocations
    solver.Add(x <= 2500)
    solver.Add(y <= 1500)
    solver.Add(z <= 4000)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = cost.solution_value()
        result = {
