    supply_constraint = solver.Constraint(0, supply[i], f'supply_{i}')
    for j in range(num_ports):
        supply_constraint.SetCoefficient(x[(i, j)], 1)

# Demand constraints
for j in range(num_ports):
    demand_constraint = solver.Constraint(demand[j], solver.infinity(), f'demand_{j}')
    for i in range(num_warehouses):
        demand_constraint.SetCoefficient(x[(i, j)], 1)

# Solve the problem
status = solver.Solve()

# Calculate the objective value
objective_value = total_cost.solution_value()

# Print the result
print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

