costs = {
    'E': {'F': 65, 'G': 10, 'H': 25, 'I': 82},
    'F': {'E': 65, 'G': 98, 'H': 42, 'I': 26},
    'G': {'E': 10, 'F': 98, 'H': 75, 'I': 72},
    'H': {'E': 25, 'F': 42, 'G': 75, 'I': 46},
    'I': {'E': 82, 'F': 26, 'G': 72, 'H': 46}
}

# Create the solver
solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

# Create binary variables for each pair of locations
x = {}
for i in locations:
    for j in locations:
        if i != j:
            x[(i, j)] = solver.IntVar(0, 1, f'x_{i}_{j}')

# Objective function: minimize total cost
objective = solver.Objective()
for i in locations:
    for j in locations:
        if i != j:
            objective.SetCoefficient(x[(i, j)], costs[i][j])
objective.SetMinimization()

# Constraints: each location has exactly one incoming and one outgoing edge
for i in locations:
    incoming = solver.Sum([x[(j, i)] for j in locations if j != i])
