from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define the time periods and required salespeople
    periods = [10, 15, 25, 20, 18, 12]

    # Create variables for each shift start time
    x = [solver.IntVar(0, solver.infinity(), f'x_{i}') for i in range(len(periods))]

    # Define the objective function: minimize total number of salespeople
    objective = solver.Objective()
    objective.SetMinimization()
    for i in range(len(x)):
        objective.SetCoefficient(x[i], 1)

    # Add constraints for each time period
    for i in range(len(periods)):
        # Calculate the number of salespeople working during period i
        # This is the sum of salespeople starting their shifts in periods that overlap with i
        # Since each shift is 8 hours, the overlapping periods are i and i-1 (with wrap-around)
        overlap = [x[i], x[(i - 1) % len(periods)]]
        constraint = solver.Constraint(periods[i], solver.infinity())
        for var in overlap:
            constraint.SetCoefficient(var, 1)

    # Solve the problem
    status = solver.Solve()

    # Extract the objective value
    objective_value = solver.Objective().Value()

    # Print the result
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
