    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    b = solver.IntVar(0, sys.maxsize, 'buses')
    c = solver.IntVar(5, sys.maxsize, 'cars')

    # Constraint 1: Total capacity must be at least 100
    solver.Add(9 * b + 4 * c >= 100)

    # Constraint 2: Number of buses must be at least one more than the number of cars
    solver.Add(b >= c + 1)

    # Objective: Minimize total number of vehicles
    solver.Minimize(b + c)

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    if status == pywraplp.Solver.OPTIMAL:
        total_vehicles = b.solution_value() + c.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": total_vehicles
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
