from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver("CBC_MIXED_INTEGER_PROGRAMMING")

    # Define decision variables
    x_c_r = solver.IntVar(0, solver.infinity(), "x_c_r")
    x_c_p = solver.IntVar(0, solver.infinity(), "x_c_p")
    x_g_r = solver.IntVar(0, solver.infinity(), "x_g_r")
    x_g_p = solver.IntVar(0, solver.infinity(), "x_g_p")
    x_v_r = solver.IntVar(0, solver.infinity(), "x_v_r")
    x_v_p = solver.IntVar(0, solver.infinity(), "x_v_p")

    # Objective function: Maximize total profit
    profit = (
        2 * x_c_r + 3 * x_c_p +
        4 * x_g_r + 5 * x_g_p +
        3 * x_v_r + 4 * x_v_p
    )
    solver.Maximize(profit)

    # Constraints
    # Regular ingredient constraint
    solver.Add(0.5 * x_c_r + 0.8 * x_g_r + 0.6 * x_v_r <= 100)
    # Premium ingredient constraint
    solver.Add(0.8 * x_c_p + 1.2 * x_g_p + 1.0 * x_v_p <= 50)
    # Production capacity constraint
    solver.Add(x_c_r + x_c_p + x_g_r + x_g_p + x_v_r + x_v_p <= 200)
    # Demand constraints
    solver.Add(x_c_r + x_c_p <= 150)
    solver.Add(x_g_r + x_g_p <= 100)
    solver.Add(x_v_r + x_v_p <= 80)

    # Solve the problem
    status = solver.Solve()

    # Extract the optimal solution
    if status == pywraplp.Solver.OPTIMAL:
        objective_value = profit.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": objective_value
        }
    else:
