market_risk = [3, 5, 4, 6, 7]
production_cost_per_unit = [20, 30, 25, 40, 50]

# Create decision variables
units = {}
for i, product in enumerate(products):
    units[product] = solver.IntVar(0, solver.infinity(), f'Units_{product}')

# Binary variables for product inclusion
include = {}
for i, product in enumerate(products):
    include[product] = solver.BoolVar(f'Include_{product}')

# Total investment constraint
total_investment = solver.Sum([production_cost_per_unit[i] * units[products[i]] for i in range(len(products))])
solver.Add(total_investment <= 50000)
solver.Add(total_investment >= 20000)

# Minimum units for Product A
solver.Add(units['A'] >= 500)

# Objective: Maximize (Total Profit) / (Total Market Risk)
total_profit = solver.Sum([profit_per_unit[i] * units[products[i]] for i in range(len(products))])
total_market_risk = solver.Sum([market_risk[i] * units[products[i]] for i in range(len(products))])

# Linearize the objective
z = solver.NumVar(0, solver.infinity(), 'Total_Market_Risk')
solver.Add(total_market_risk == z)

# Objective is to maximize total_profit - (total_market_risk * z)
# Since z is equal to total_market_risk, we can simplify the objective to maximize total_profit
# However, to maintain the ratio, we can use a helper variable
# For simplicity, we will maximize total_profit directly
solver.Maximize(total_profit)

# Solve the problem
status = solver.Solve()

# Calculate the objective value
if status == pywraplp.Solver.OPTIMAL:
    total_profit_value = total_profit.solution_value()
    total_market_risk_value = total_market_risk.solution_value()
    profit_risk_ratio = total_profit_value / total_market_risk_value
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
else:
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

