import numpy as np
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver("CBC_MIXED_INTEGER_PROGRAMMING")

    # Define blends
    blends = ['Zen', 'Energy', 'Relax', 'Extra', 'Premium']

    # Define parameters
    initial_profit = {
        'Zen': 5,
        'Energy': 7,
        'Relax': 6,
        'Extra': 8,
        'Premium': 10
    }

    special_tea_leaves_required = {
        'Zen': 10,
        'Energy': 15,
        'Relax': 12,
        'Extra': 18,
        'Premium': 20
    }

    demand = {
        'Zen': 200,
        'Energy': 250,
        'Relax': 300,
        'Extra': 150,
        'Premium': 100
    }

    # Create decision variables
    x = {}
    y = {}
    for blend in blends:
        x[blend] = solver.IntVar(0, demand[blend], f"x_{blend}")
        y[blend] = solver.IntVar(0, demand[blend], f"y_{blend}")

    # Add constraints
    # Special tea leaves constraint
    tea_leaves_constraint = solver.Constraint(0, 1000, "tea_leaves")
    for blend in blends:
        tea_leaves_constraint.SetCoefficient(x[blend], special_tea_leaves_required[blend])

    # Production capacity constraint
    production_capacity_constraint = solver.Constraint(0, 650, "production_capacity")
    for blend in blends:
        production_capacity_constraint.SetCoefficient(x[blend], 1)

    # Link y_i to x_i for the nonlinear profit term
    for blend in blends:
        # y_i = max(x_i - 50, 0) * 0.01
        # This is linearized by introducing a binary variable z_i and constraints
        z = solver.IntVar(0, 1, f"z_{blend}")
        solver.Add(x[blend] - 50 <= z * demand[blend])
        solver.Add(z <= x[blend] / 50)
        solver.Add(z >= x[blend] / 50 - 1)
        solver.Add(y[blend] == z * 0.01)

    # Objective function
    objective = solver.Objective()
    for blend in blends:
        objective.SetCoefficient(x[blend], initial_profit[blend])
        objective.SetCoefficient(y[blend], 0.01)
    objective.SetMaximization()

    # Solve the problem
    status = solver.Solve()

    # Extract the solution
    total_profit = 0
    for blend in blends:
        total_profit += initial_profit[blend] * x[blend].solution_value()
        total_profit += 0.01 * y[blend].solution_value()

    # Prepare the result
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_SOLVED",
        "objective_value": total_profit
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == "__main__":
    main()

